<script setup>import{onMounted,ref}from'vue';import{api}from'../../api/http.js';import PageHeader from'../../components/common/PageHeader.vue';import T from'../../components/common/WorkspaceTable.vue';const data=ref({profile:null,hr_requests:[],finance_requests:[],attendance:[]}),error=ref(''),form=ref({kind:'hr',request_type:'Leave',reason:'',amount:0,start_date:'',end_date:''});async function load(){try{data.value=await api.get('/workspace/self')}catch(x){error.value=x.message}}async function save(){try{await api.post('/workspace/self/request',form.value);form.value.reason='';await load()}catch(x){error.value=x.message}}onMounted(load)</script><template><PageHeader title="Employee Self-Service" description="View your profile and submit requests."/><p v-if="error" class="form-error">{{error}}</p><section v-if="data.profile" class="profile-card"><h2>{{data.profile.full_name}}</h2><p>{{data.profile.employee_no}} · {{data.profile.position}} · {{data.profile.department}}</p><p>Leave balance: {{data.profile.leave_balance}}</p></section><form class="inline-form" @submit.prevent="save"><select v-model="form.kind"><option value="hr">HR request</option><option value="finance">Finance request</option></select><select v-model="form.request_type"><option v-if="form.kind==='hr'">Leave</option><option v-if="form.kind==='hr'">Overtime</option><option v-if="form.kind==='hr'">Other</option><option v-if="form.kind==='finance'">Reimbursement</option><option v-if="form.kind==='finance'">Purchase</option></select><input v-if="form.kind==='finance'" v-model.number="form.amount" type="number" step=".01" placeholder="Amount"><input v-model="form.reason" placeholder="Reason or description" required><button class="primary-button">Submit request</button></form><h2>My HR requests</h2><T :columns="[{key:'created_at',label:'Date'},{key:'request_type',label:'Type'},{key:'reason',label:'Reason'},{key:'status',label:'Status'}]" :rows="data.hr_requests"/><h2 class="section-title">My finance requests</h2><T :columns="[{key:'created_at',label:'Date'},{key:'request_type',label:'Type'},{key:'amount',label:'Amount'},{key:'status',label:'Status'}]" :rows="data.finance_requests"/></template>